/// <summary>
///     AVA <c>parmQuery</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <param name="_packedQuery">
///     <c>str</c> as type
/// </param>
/// <returns>
///     <c>str</c> as return value
/// </returns>
///
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(AVABOSProvisionReportQry))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
///     AVA <c>validate</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean validate()
{
    boolean retVal;

    retVal = true;

    if(retVal)
    {
        if( (       contractCustAccount != '' 
                &&  contractTOSId       != ''   )
            ||
            (       contractCustAccount == ''
                &&  contractTOSId       == ''   )   )
        {
            retVal = checkFailed(strFmt("@NDX:NXAP1P2", "@NDX:NXAEitherAllianceOrCustomer", ''));

        }
    }
    return retVal;
}
